const D = { energy:.6, scale:1, hue:32, speed:1, density:.5, x:.56, y:.86, chub:.5, fluff:.5, tail:.6, pose:'groove', act:'perform', style:'sumi', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---------- helpers ----------
const u = Math.min(width, height);
const sc = (u/600) * P.scale;
const ax = P.x*width, ay = P.y*height;
const H = ((P.hue % 360) + 360) % 360;
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat;
S.lastBeat = K.beat;

// ---------- rhythm ----------
const e = P.energy, sp = P.speed;
const bt = K.beat * sp, ph = K.phase;
const pulse = Math.min(1, K.pulse*(0.55 + 0.5*K.intensity) + A.bass*0.6);
const liftArc = Math.sin(ph * PI);
const breathe = Math.sin(K.t*1.05)*0.5 + 0.5;
const sway = Math.sin(bt*TAU/8);
const purr = Math.sin(K.t*8)*0.5 + 0.5; // fast tremor for xray/sumi grain feel

// ---------- act: slow dramaturgy over minutes ----------
let pose = P.pose;
if (P.act === 'wander') {
  const cyclePose = ['idle','prowl','groove','pounce'][K.section % 4];
  pose = cyclePose;
}

// ---------- style setup ----------
const style = P.style;
const isXray = style === 'xray';
let bH, bS, bB, accH, accS, accB;
if (style === 'noir')      { bH=H; bS=16; bB=11; accH=(H+40)%360; accS=30; accB=90; }
else if (style === 'neon') { bH=H; bS=68; bB=9;  accH=(H+150)%360; accS=90; accB=100; }
else if (style === 'xray') { bH=(H+195)%360; bS=62; bB=20; accH=(H+195)%360; accS=20; accB=100; }
else /* sumi */            { bH=H; bS=14; bB=15; accH=(H+8)%360; accS=55; accB=88; }

function fillFor(depth) { // depth 0 dark .. 1 lit
  if (isXray) { noStroke(); fill(bH, bS, Math.min(70, bB + depth*14), 15 + depth*10); return; }
  if (style === 'neon') { noStroke(); fill(bH, bS, bB + depth*5); return; }
  noStroke(); fill(bH, Math.max(0, bS - depth*3), bB + depth*(style === 'noir' ? 60 : 26));
}

// =============== rig math ===============
const chub = P.chub, fluff = P.fluff, tl = P.tail;
let bodyY=0, bodyX=0, lean=0, headDX=0, headDY=0, crouch=0, springF=0, mouth=0, earBack=0, blink=0;
let pawA=0, pawB=0;

if (pose === 'groove') {
  bodyY = -liftArc*(6 + 15*e) - K.swell*2.5;
  bodyX = sway*5;
  headDY = -pulse*4.5 - liftArc*2;
  headDX = sway*4;
  lean = sway*0.06;
  pawA = Math.max(0, Math.sin(bt*TAU))*(7 + 6*e);
  pawB = Math.max(0, -Math.sin(bt*TAU))*(7 + 6*e);
  blink = (((bt*0.5) % 4) > 3.86) ? 1 : 0;
} else if (pose === 'idle') {
  bodyY = -breathe*3 - K.swell*1.5;
  bodyX = Math.sin(K.t*0.25)*2;
  headDY = Math.sin(bt*TAU/4)*1.6 + pulse*1.4;
  headDX = Math.sin(K.t*0.32)*4;
  lean = Math.sin(K.t*0.2)*0.025;
  blink = (((K.t*0.5) % 5) > 4.85) ? 1 : 0;
} else if (pose === 'pounce') {
  const cr = Math.pow(Math.max(0, (0.72 - ph)/0.72), 1.5);
  crouch = cr; springF = pulse;
  bodyY = cr*9 - pulse*(26 + 30*e);
  bodyX = -pulse*(9 + 10*e);
  headDY = cr*11 - pulse*8;
  headDX = -cr*8 - pulse*15;
  earBack = cr; mouth = pulse;
  blink = 0;
} else { // prowl
  crouch = 0.7;
  bodyY = -Math.abs(Math.sin(bt*TAU))*3 - 2;
  bodyX = Math.sin(bt*TAU/4)*5;
  headDX = Math.sin(K.t*0.4)*6 - 6;
  headDY = 7 + Math.sin(bt*TAU/4)*2;
  pawA = Math.max(0, Math.sin(bt*TAU))*8;
  pawB = Math.max(0, Math.sin(bt*TAU + PI))*8;
  lean = Math.sin(bt*TAU/4)*0.04;
}

// audio accents on top of the baseline
const glow = A.bass*0.5 + A.rms*0.6;
mouth = Math.min(1, mouth + A.mid*0.3);

// ---------- posture anchors (model units, facing LEFT) ----------
const bx = bodyX, byo = bodyY;
const haunchC = [46 + bx*0.3, -40 + byo*0.5];
const Sx = -30 + bx + headDX*0.25 - crouch*20;
const Sy = -128 + byo + crouch*46;
const HDx = Sx - 42 - crouch*20 + headDX;
const HDy = Sy - 52 + crouch*28 + headDY;
const hr = 56 * (0.9 + chub*0.22);

// =============== DRAW ===============
push();
translate(ax, ay);
scale(sc);
rotate(lean*0.4);

// contact shadow
noStroke(); fill(0, 0, 0, 22); ellipse(bx*0.5 - 8, 6, 210 + chub*40, 20);

// ---------- neon underglow ----------
if (style === 'neon') { push(); blendMode(ADD); noStroke(); fill(accH, accS, accB, 6 + glow*22 + pulse*4); ellipse(-20 + bx, -80, 360, 320); blendMode(BLEND); pop(); }

// ---------- TAIL (drawn behind body) ----------
(function(){
  const rootX = haunchC[0] + 46, rootY = haunchC[1] + 6;
  const swishA = pose === 'idle' ? Math.sin(K.t*1.3)*0.5 : Math.sin(bt*TAU/2)*0.7*(0.5 + e*0.6);
  const flick = Math.sin(K.t*3.1)*0.18;
  const len = (120 + tl*120);
  const c1x = rootX + 30, c1y = rootY - len*0.4 + swishA*20;
  const c2x = rootX + 26 + Math.cos(swishA + flick)*70, c2y = rootY - len*0.75 + Math.sin(swishA)*24;
  const tipx = rootX + 8 + Math.cos(swishA*1.4 + flick + 0.6)*98, tipy = rootY - len + Math.sin(swishA*1.2)*30;
  if (isXray) {
    stroke(bH, 40, 100, 60); strokeWeight(3); noFill();
    bezier(rootX, rootY, c1x, c1y, c2x, c2y, tipx, tipy);
    for (let i=0;i<=6;i++){ const tt=i/6; const jx=bezierPoint(rootX,c1x,c2x,tipx,tt), jy=bezierPoint(rootY,c1y,c2y,tipy,tt); fill(bH,20,100,60); noStroke(); circle(jx,jy,4); stroke(bH,40,100,50); strokeWeight(2); }
  } else {
    noFill();
    const steps = 5;
    for (let i=0;i<steps;i++){
      const w = (18 + fluff*10) * (1 - i/steps*0.7);
      strokeWeight(w);
      if (style==='neon'){ push(); blendMode(ADD); stroke(bH,bS,bB+18,90); }
      else stroke(bH, Math.max(0,bS-4), bB + (style==='noir'?18:8));
      const t0=i/steps, t1=(i+1)/steps;
      const x0=bezierPoint(rootX,c1x,c2x,tipx,t0), y0=bezierPoint(rootY,c1y,c2y,tipy,t0);
      const x1=bezierPoint(rootX,c1x,c2x,tipx,t1), y1=bezierPoint(rootY,c1y,c2y,tipy,t1);
      line(x0,y0,x1,y1);
      if (style==='neon') pop();
    }
    // tail tip accent
    noStroke(); fill(accH, accS*0.6, style==='neon'?accB:bB+20, style==='neon'?90:100); circle(tipx, tipy, 14 + fluff*6);
  }
})();

// ---------- BODY MASSES ----------
// haunch (rear)
fillFor(0.15);
push(); translate(haunchC[0], haunchC[1]); rotate(0.1);
ellipse(0, 0, (128 + chub*46), (132 + chub*30)); pop();
// torso arc from haunch to shoulder
fillFor(0.35);
beginShape();
vertex(haunchC[0]+10, haunchC[1]-58);
bezierVertex(haunchC[0]-10, haunchC[1]-96, Sx+30, Sy-30, Sx+2, Sy-8);
vertex(Sx-18, Sy+30);
bezierVertex(haunchC[0]-30, haunchC[1]+64, haunchC[0]+30, haunchC[1]+60, haunchC[0]+58, haunchC[1]+18);
endShape(CLOSE);
// chest / shoulder mass
fillFor(0.5);
push(); translate(Sx-4, Sy+6); rotate(lean*0.5);
ellipse(0, 0, (78 + chub*30), (104 + chub*20)); pop();

// ---------- FRONT LEGS + PAWS ----------
(function(){
  const legTopX = Sx - 20, legTopY = Sy + 26;
  const spread = 20 + crouch*10;
  const groundY = 6 - crouch*2;
  for (let s=0;s<2;s++){
    const lift = s===0 ? pawA : pawB;
    const fx = legTopX - spread*0.5 + s*spread - crouch*14;
    const px = fx - 4 - crouch*4;
    const py = groundY - lift;
    fillFor(0.3);
    if (isXray) {
      stroke(bH,40,100,60); strokeWeight(3); noFill();
      line(legTopX + s*10 - 4, legTopY, px, py);
      noStroke(); fill(bH,20,100,60); circle(px,py,5);
    } else {
      noStroke();
      // leg
      push();
      const dx=px-(legTopX+s*8), dy=py-legTopY; const ang=Math.atan2(dy,dx);
      translate(legTopX+s*8, legTopY); rotate(ang - PI/2);
      const ll=Math.sqrt(dx*dx+dy*dy);
      rectMode(CENTER); rect(0, ll/2, 18 + fluff*4, ll, 9); rectMode(CORNER);
      pop();
      // paw
      ellipse(px, py+2, 26 + fluff*4, 16);
    }
  }
})();

// ---------- HEAD ----------
push();
translate(HDx, HDy);
rotate(headDX*0.006 + lean*0.6);
// ears
const earLen = 34 * (0.8 + fluff*0.5);
for (let s=-1;s<=1;s+=2){
  const ebx = s*hr*0.34, eby = -hr*0.42;
  const tipx = ebx + s*10 - earBack*s*10, tipy = eby - earLen + earBack*6;
  if (isXray) {
    stroke(bH,40,100,55); strokeWeight(2.4); noFill();
    triangle(ebx - s*18, eby+6, tipx, tipy, ebx + s*14, eby+2);
  } else {
    fillFor(0.25); noStroke();
    triangle(ebx - s*20, eby+8, tipx, tipy, ebx + s*16, eby+2);
    // inner ear
    fill(accH, accS, accB*(style==='neon'?0.7:1), style==='neon'?70:100);
    triangle(ebx - s*10, eby+2, tipx - s*2, tipy+10, ebx + s*8, eby-2);
  }
}
// skull / head mass
if (isXray) {
  stroke(bH,45,100,70); strokeWeight(2.6); fill(bH,bS,bB+10,14);
  ellipse(0, 0, hr*1.9, hr*1.7);
  noFill(); stroke(bH,30,100,45); strokeWeight(1.4);
  for (let i=0;i<4;i++) line(-hr*0.8, -hr*0.3+i*hr*0.28, hr*0.7, -hr*0.3+i*hr*0.28);
} else {
  fillFor(0.55);
  ellipse(0, 0, hr*1.92, hr*1.72);
  // muzzle
  fillFor(style==='noir'?0.75:0.4);
  ellipse(-hr*0.5, hr*0.28, hr*0.9, hr*0.66);
}
// face (skip heavy detail for xray)
const eyeOpen = (1 - blink);
if (isXray) {
  noStroke(); fill(bH, 30, 100, 60);
  ellipse(-hr*0.44, -hr*0.1, 16, 20); ellipse(hr*0.18, -hr*0.14, 16, 20);
  stroke(bH,40,100,40); strokeWeight(1.2); noFill();
  line(-hr*0.3, hr*0.3, hr*0.05, hr*0.3);
} else {
  // eyes
  for (let s=-1;s<=1;s+=2){
    const ex = s<0 ? -hr*0.42 : hr*0.2, ey = -hr*0.12;
    noStroke();
    if (style==='neon'){ push(); blendMode(ADD); fill(accH,accS,accB, 60 + glow*30); ellipse(ex, ey, 22, 26*eyeOpen+2); blendMode(BLEND); pop(); }
    fill(accH, style==='noir'?70:accS, style==='neon'?30:accB);
    ellipse(ex, ey, 20, 26*eyeOpen + 2);
    // pupil (vertical slit) tracks head sway
    fill(0, 0, style==='neon'?0:8);
    ellipse(ex + headDX*0.02, ey, 5 + (1-eyeOpen)*8, (18*eyeOpen)+1);
    if (eyeOpen > 0.5){ fill(0,0,100,70); circle(ex-3, ey-5, 4); }
  }
  // nose
  fill(accH, accS, style==='neon'?60:accB);
  triangle(-hr*0.5, hr*0.16, -hr*0.5-6, hr*0.16, -hr*0.5-3, hr*0.16+7);
  // mouth
  stroke(bH, bS, style==='neon'?70:Math.min(90,bB+35)); strokeWeight(2); noFill();
  const mo = mouth*10;
  arc(-hr*0.5-3, hr*0.24, 16, 10+mo, 0.2, PI-0.2);
  if (mouth>0.25){ noStroke(); fill(accH, 60, style==='neon'?50:70); ellipse(-hr*0.5-3, hr*0.30, 8, mo*0.8); }
  // whiskers
  stroke(0,0,style==='neon'?90:Math.min(95,bB+55), 70); strokeWeight(1);
  for (let i=-1;i<=1;i++){
    const wy = hr*0.16 + i*6;
    const wob = Math.sin(K.t*2 + i)*3 + headDX*0.05;
    line(-hr*0.55, wy, -hr*1.15, wy - 8 + i*8 + wob);
    line(-hr*0.55, wy, -hr*1.1, wy + 10 + i*6 + wob);
  }
}
pop(); // head

// ---------- sumi dry-brush texture over body ----------
if (style === 'sumi') {
  const n = Math.round(12 + P.density*26);
  for (let i=0;i<n;i++){
    const gx = haunchC[0] + (fr(i*3+1)*2-1)*90;
    const gy = -60 + (fr(i*3+2))*(-70) - fr(i*7)*20;
    stroke(bH, bS+6, bB - 6, 20 + fr(i*5)*22); strokeWeight(1 + fr(i*9)*2);
    const a = fr(i*11)*PI;
    line(gx, gy, gx + Math.cos(a)*(6+fr(i)*10), gy + Math.sin(a)*(6+fr(i)*10));
  }
}
// noir raking highlight (form from light, upper-left)
if (style === 'noir') {
  push(); blendMode(ADD); noStroke();
  fill(accH, accS, accB, 10 + K.swell*6);
  ellipse(Sx-30, Sy-20, 90, 120);
  ellipse(HDx - hr*0.4, HDy - hr*0.4, hr*1.2, hr*1.2);
  blendMode(BLEND); pop();
}
// xray joint glow at spine
if (isXray) {
  push(); blendMode(ADD); noStroke();
  for (let i=0;i<5;i++){ const tt=i/4; const jx=haunchC[0]-tt*(haunchC[0]-Sx)*1.0; const jy=haunchC[1]-40-tt*60; fill(bH,30,100,30+pulse*30); circle(jx, jy, 8+pulse*6); }
  blendMode(BLEND); pop();
}

pop(); // world
blendMode(BLEND);
